import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

// Scaled dot-product attention specialized for the reference shapes:
//   Q, K, V : (2, 32, 256, 1024) fp16, contiguous
//   out = softmax(Q @ K^T * (1/sqrt(1024))) @ V
// grid = (sequence_length=256, batch*heads=64, 1), block = (256, 1, 1)
// Block (ctaid.x = query row, ctaid.y = batch*head) computes one output row.
// Thread t owns head-dims {t, 256+t, 512+t, 768+t}; every block is full.

.visible .entry attention_kernel(
    .param .u64 pQ,
    .param .u64 pK,
    .param .u64 pV,
    .param .u64 pO
)
{
    .reg .pred %p<8>;
    .reg .b16 %rh<8>;
    .reg .b32 %r<32>;
    .reg .b64 %rd<16>;
    .reg .f32 %f<32>;

    .shared .align 4 .f32 scores[256];
    .shared .align 4 .f32 red[8];
    .shared .align 4 .f32 bcast[1];

    ld.param.u64 %rd0, [pQ];
    ld.param.u64 %rd1, [pK];
    ld.param.u64 %rd2, [pV];
    ld.param.u64 %rd3, [pO];

    mov.u32 %r0, %tid.x;        // tid   (0..255)
    mov.u32 %r1, %ctaid.x;      // query row index
    mov.u32 %r2, %ctaid.y;      // bh = batch*32 + head

    shl.b32 %r3, %r2, 8;        // bh*256
    add.u32 %r3, %r3, %r1;      // global row
    shl.b32 %r4, %r3, 10;       // qoff = row*1024 (elements)
    shl.b32 %r5, %r2, 18;       // kvbase = bh*262144 (elements)

    and.b32 %r6, %r0, 31;       // lane
    shr.u32 %r7, %r0, 5;        // warp id

    // ---- load this thread's 4 query elements (fp16 -> fp32) ----
    add.u32 %r8, %r4, %r0;
    shl.b32 %r8, %r8, 1;        // bytes
    cvt.u64.u32 %rd4, %r8;
    add.u64 %rd4, %rd4, %rd0;
    ld.global.u16 %rh0, [%rd4];
    ld.global.u16 %rh1, [%rd4+512];
    ld.global.u16 %rh2, [%rd4+1024];
    ld.global.u16 %rh3, [%rd4+1536];
    cvt.f32.f16 %f0, %rh0;      // q0
    cvt.f32.f16 %f1, %rh1;      // q1
    cvt.f32.f16 %f2, %rh2;      // q2
    cvt.f32.f16 %f3, %rh3;      // q3

    // ---- pass 1: scores[j] = (q . k_j) * (1/32) ----
    mov.u32 %r9, 0;             // j
KEY_LOOP:
    shl.b32 %r10, %r9, 10;      // j*1024
    add.u32 %r10, %r10, %r5;
    add.u32 %r10, %r10, %r0;
    shl.b32 %r10, %r10, 1;
    cvt.u64.u32 %rd5, %r10;
    add.u64 %rd5, %rd5, %rd1;
    ld.global.u16 %rh0, [%rd5];
    ld.global.u16 %rh1, [%rd5+512];
    ld.global.u16 %rh2, [%rd5+1024];
    ld.global.u16 %rh3, [%rd5+1536];
    cvt.f32.f16 %f4, %rh0;
    cvt.f32.f16 %f5, %rh1;
    cvt.f32.f16 %f6, %rh2;
    cvt.f32.f16 %f7, %rh3;
    mul.f32 %f8, %f0, %f4;
    fma.rn.f32 %f8, %f1, %f5, %f8;
    fma.rn.f32 %f8, %f2, %f6, %f8;
    fma.rn.f32 %f8, %f3, %f7, %f8;

    // intra-warp sum reduction of %f8
    mov.b32 %r20, %f8;
    shfl.sync.down.b32 %r21, %r20, 16, 31, 0xffffffff;
    mov.b32 %f9, %r21;
    add.f32 %f8, %f8, %f9;
    mov.b32 %r20, %f8;
    shfl.sync.down.b32 %r21, %r20, 8, 31, 0xffffffff;
    mov.b32 %f9, %r21;
    add.f32 %f8, %f8, %f9;
    mov.b32 %r20, %f8;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f9, %r21;
    add.f32 %f8, %f8, %f9;
    mov.b32 %r20, %f8;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f9, %r21;
    add.f32 %f8, %f8, %f9;
    mov.b32 %r20, %f8;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f9, %r21;
    add.f32 %f8, %f8, %f9;

    setp.eq.u32 %p0, %r6, 0;
    mov.u32 %r11, red;
    shl.b32 %r12, %r7, 2;
    add.u32 %r11, %r11, %r12;
    @%p0 st.shared.f32 [%r11], %f8;     // red[wid] = warp sum
    bar.sync 0;

    // warp 0 reduces the 8 partial sums
    mov.u32 %r11, red;
    shl.b32 %r12, %r6, 2;
    add.u32 %r11, %r11, %r12;
    mov.f32 %f10, 0f00000000;
    setp.lt.u32 %p2, %r6, 8;
    setp.eq.u32 %p1, %r7, 0;
    and.pred %p3, %p1, %p2;
    @%p3 ld.shared.f32 %f10, [%r11];
    setp.ne.u32 %p4, %r7, 0;
    @%p4 bra REDUCE_DONE;
    mov.b32 %r20, %f10;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f11, %r21;
    add.f32 %f10, %f10, %f11;
    mov.b32 %r20, %f10;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f11, %r21;
    add.f32 %f10, %f10, %f11;
    mov.b32 %r20, %f10;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f11, %r21;
    add.f32 %f10, %f10, %f11;
    mul.f32 %f10, %f10, 0f3D000000;     // scale = 1/sqrt(1024) = 0.03125
    mov.u32 %r13, scores;
    shl.b32 %r14, %r9, 2;
    add.u32 %r13, %r13, %r14;
    setp.eq.u32 %p0, %r6, 0;
    @%p0 st.shared.f32 [%r13], %f10;    // scores[j]
REDUCE_DONE:
    bar.sync 0;
    add.u32 %r9, %r9, 1;
    setp.lt.u32 %p0, %r9, 256;
    @%p0 bra KEY_LOOP;

    // ---- softmax: block max over scores ----
    mov.u32 %r13, scores;
    shl.b32 %r14, %r0, 2;
    add.u32 %r15, %r13, %r14;
    ld.shared.f32 %f12, [%r15];         // s = scores[tid]

    mov.f32 %f13, %f12;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 16, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 8, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    setp.eq.u32 %p0, %r6, 0;
    mov.u32 %r11, red;
    shl.b32 %r12, %r7, 2;
    add.u32 %r11, %r11, %r12;
    @%p0 st.shared.f32 [%r11], %f13;
    bar.sync 0;

    mov.u32 %r11, red;
    shl.b32 %r12, %r6, 2;
    add.u32 %r11, %r11, %r12;
    mov.f32 %f15, 0fFF800000;           // -inf
    setp.lt.u32 %p2, %r6, 8;
    setp.eq.u32 %p1, %r7, 0;
    and.pred %p3, %p1, %p2;
    @%p3 ld.shared.f32 %f15, [%r11];
    setp.ne.u32 %p4, %r7, 0;
    @%p4 bra MAX_DONE;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f15, %f15, %f14;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f15, %f15, %f14;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f15, %f15, %f14;
    setp.eq.u32 %p0, %r6, 0;
    mov.u32 %r11, bcast;
    @%p0 st.shared.f32 [%r11], %f15;
MAX_DONE:
    bar.sync 0;
    mov.u32 %r11, bcast;
    ld.shared.f32 %f16, [%r11];         // row max

    // ---- softmax: e = exp(s - max), block sum of e ----
    sub.f32 %f17, %f12, %f16;
    mul.f32 %f17, %f17, 0f3FB8AA3B;     // * log2(e)
    ex2.approx.f32 %f18, %f17;
    st.shared.f32 [%r15], %f18;         // scores[tid] = e

    mov.f32 %f13, %f18;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 16, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 8, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    setp.eq.u32 %p0, %r6, 0;
    mov.u32 %r11, red;
    shl.b32 %r12, %r7, 2;
    add.u32 %r11, %r11, %r12;
    @%p0 st.shared.f32 [%r11], %f13;
    bar.sync 0;

    mov.u32 %r11, red;
    shl.b32 %r12, %r6, 2;
    add.u32 %r11, %r11, %r12;
    mov.f32 %f15, 0f00000000;
    setp.lt.u32 %p2, %r6, 8;
    setp.eq.u32 %p1, %r7, 0;
    and.pred %p3, %p1, %p2;
    @%p3 ld.shared.f32 %f15, [%r11];
    setp.ne.u32 %p4, %r7, 0;
    @%p4 bra SUM_DONE;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f15, %f15, %f14;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f15, %f15, %f14;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f15, %f15, %f14;
    setp.eq.u32 %p0, %r6, 0;
    mov.u32 %r11, bcast;
    @%p0 st.shared.f32 [%r11], %f15;
SUM_DONE:
    bar.sync 0;
    mov.u32 %r11, bcast;
    ld.shared.f32 %f19, [%r11];         // softmax denominator
    mov.f32 %f20, 0f3F800000;           // 1.0f
    div.rn.f32 %f21, %f20, %f19;        // 1 / sum

    // ---- pass 2: out = (sum_j e_j * v_j) / sum ----
    mov.f32 %f22, 0f00000000;
    mov.f32 %f23, 0f00000000;
    mov.f32 %f24, 0f00000000;
    mov.f32 %f25, 0f00000000;
    mov.u32 %r9, 0;
OUT_LOOP:
    mov.u32 %r13, scores;
    shl.b32 %r14, %r9, 2;
    add.u32 %r13, %r13, %r14;
    ld.shared.f32 %f26, [%r13];         // e_j (broadcast)

    shl.b32 %r10, %r9, 10;
    add.u32 %r10, %r10, %r5;
    add.u32 %r10, %r10, %r0;
    shl.b32 %r10, %r10, 1;
    cvt.u64.u32 %rd5, %r10;
    add.u64 %rd5, %rd5, %rd2;
    ld.global.u16 %rh0, [%rd5];
    ld.global.u16 %rh1, [%rd5+512];
    ld.global.u16 %rh2, [%rd5+1024];
    ld.global.u16 %rh3, [%rd5+1536];
    cvt.f32.f16 %f4, %rh0;
    cvt.f32.f16 %f5, %rh1;
    cvt.f32.f16 %f6, %rh2;
    cvt.f32.f16 %f7, %rh3;
    fma.rn.f32 %f22, %f26, %f4, %f22;
    fma.rn.f32 %f23, %f26, %f5, %f23;
    fma.rn.f32 %f24, %f26, %f6, %f24;
    fma.rn.f32 %f25, %f26, %f7, %f25;
    add.u32 %r9, %r9, 1;
    setp.lt.u32 %p0, %r9, 256;
    @%p0 bra OUT_LOOP;

    mul.f32 %f22, %f22, %f21;
    mul.f32 %f23, %f23, %f21;
    mul.f32 %f24, %f24, %f21;
    mul.f32 %f25, %f25, %f21;

    // ---- store output row (fp32 -> fp16) ----
    cvt.rn.f16.f32 %rh0, %f22;
    cvt.rn.f16.f32 %rh1, %f23;
    cvt.rn.f16.f32 %rh2, %f24;
    cvt.rn.f16.f32 %rh3, %f25;
    add.u32 %r8, %r4, %r0;
    shl.b32 %r8, %r8, 1;
    cvt.u64.u32 %rd4, %r8;
    add.u64 %rd4, %rd4, %rd3;
    st.global.u16 [%rd4], %rh0;
    st.global.u16 [%rd4+512], %rh1;
    st.global.u16 [%rd4+1024], %rh2;
    st.global.u16 [%rd4+1536], %rh3;

    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("attention_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        out = torch.empty(Q.shape, dtype=Q.dtype, device=Q.device)
        batch_size, num_heads, sequence_length, embedding_dimension = Q.shape
        module = _get_ptx_module()
        module.launch(
            "attention_kernel",
            grid=(sequence_length, batch_size * num_heads, 1),
            block=(256, 1, 1),
            arguments=[Q, K, V, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )
        return out

